import hashlib,json,os,re,statistics,subprocess
from pathlib import Path
out=Path(__file__).resolve().parent
variants={
 'wasm_llvm_x64_bdwgc':[str(out.parent/'wasm-llvm/cpu')],
 'wasm_llvm_x64_arena':[str(out/'x64')],
 'wasm_llvm_i686_arena':[str(out/'i686')],
 'old_ssa_i686':['/tmp/snail-native-ssa-20261010/build/native-ssa/fast'],
}
os.sched_setaffinity(0,{2})
records=[]
def sample(name,command):
 text=subprocess.check_output([*command,'64'],text=True)
 assert int(re.search(r'checksum: (\d+)',text)[1])==269118144,text
 if name.endswith('arena'):assert 'timed allocations: 0' in text,text
 return {'variant':name,'elapsed_seconds':float(re.search(r'elapsed: ([\d.]+) s',text)[1]),'checksum':269118144}
for name,cmd in variants.items():sample(name,cmd)
items=list(variants.items())
for i in range(12):
 offset=i%len(items)
 for name,cmd in items[offset:]+items[:offset]:
  value=sample(name,cmd);value['round']=i+1;records.append(value)
medians={name:statistics.median(r['elapsed_seconds'] for r in records if r['variant']==name) for name in variants}
report={'method':'12 rotated rounds CPU 2, one warmup each, 64 repetitions 22..25 weighted checksum; internal monotonic timer; no build/startup included', 'scope':'Identical current LLVM with i64 reference words; only target triple changes. Arena variants replace BDWGC initialization allocations with fixed static zeroed storage and abort on any timed allocation. CPU fixture only; no GC claim.', 'medians':medians,'samples':records,'commands':variants,'sha256':{name:hashlib.sha256(Path(cmd[0]).read_bytes()).hexdigest() for name,cmd in variants.items()}}
(out/'results.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(medians,indent=2))
